namespace HardSlice.Tool.Tests;

// PB-086: dotnet hardslice upgrade, which brings a generated solution to the template of the version of the tool. Ghostline,
// generated by an earlier build of the template, differed from a new generation in about forty files, protected ones mixed with
// files it had changed, with nothing to tell which to take as is and which to merge. These tests run the command on a git
// repository of a solution, with the generation of the template replaced by the files it is given.
public sealed class UpgradeCommandTests : IDisposable
{
    private readonly TemporarySolution _solution = new();
    private readonly FakeGenerator _generator = new();

    public UpgradeCommandTests()
    {
        // The solution as an earlier template generated it, then completed by the application.
        _solution.Write("AGENTS.md", "# Demo\n\nGolden rules:\n\n1. One slice per use case.\n\n## Modules\n\n- `Rooms`: the rooms of the building.\n");
        _solution.Write("src/Demo/Program.cs", "var app = builder.Build();\napp.Run();\n");
        _solution.Write("src/Demo/Features/Rooms/RoomsModule.cs", "namespace Demo.Features.Rooms;\n");
        _solution.Write("src/Demo/Features/Rooms/RenameRoom/RenameRoom.cs", "namespace Demo.Features.Rooms.RenameRoom;\n");
        _solution.Write(".claude/skills/add-slice/SKILL.md", "---\nname: add-slice\n---\nOld skill.\n");
        _solution.Write("docs/rules/HS016.md", "# HS016\n");
        _solution.Write("scripts/check.sh", "dotnet hardslice check\n");
        _solution.Write("tests/Demo.ArchitectureTests/SliceTests.cs", "// architecture\n");
        _solution.Write(".gitignore", "bin/\nobj/\n");
        Git("init", "--quiet");
        Commit();

        // The template of the version of the tool: a new rule sheet and a new file of Shared, a skill and AGENTS.md changed.
        _generator.Files["AGENTS.md"] = "# Demo\n\nGolden rules:\n\n1. One slice per use case.\n2. Test every slice.\n\n## Modules\n\n- None yet.\n";
        _generator.Files["src/Demo/Program.cs"] = "var app = builder.Build();\napp.Run();\n";
        _generator.Files[".claude/skills/add-slice/SKILL.md"] = "---\nname: add-slice\n---\nNew skill.\n";
        _generator.Files["docs/rules/HS016.md"] = "# HS016\n";
        _generator.Files["docs/rules/HS020.md"] = "# HS020\n";
        _generator.Files["scripts/check.sh"] = "dotnet hardslice check\n";
        _generator.Files["tests/Demo.ArchitectureTests/SliceTests.cs"] = "// architecture\n";
        _generator.Files["src/Demo/Shared/Http/DomainExceptionHandler.cs"] = "namespace Demo.Shared.Http;\n";
        _generator.Files[".config/dotnet-tools.json"] = "{}";
        _generator.Files["Directory.HardSlice.props"] = File.ReadAllText(Path.Combine(_solution.Root, "Directory.HardSlice.props"));
        _generator.Files["Directory.Packages.props"] = File.ReadAllText(Path.Combine(_solution.Root, "Directory.Packages.props"));
        _generator.Files["Demo.slnx"] = File.ReadAllText(Path.Combine(_solution.Root, "Demo.slnx"));
        _generator.Files[".gitignore"] = "bin/\nobj/\n";
        foreach (var project in _solution.TestProjects)
            _generator.Files[project] = File.ReadAllText(Path.Combine(_solution.Root, project));
    }

    public void Dispose() => _solution.Dispose();

    [Fact]
    public void Rewrites_the_files_of_the_template_adds_the_new_ones_and_lists_the_files_of_the_application_with_their_diff()
    {
        var applicationAgents = Read("AGENTS.md");

        var (exitCode, output, error) = Upgrade();

        exitCode.ShouldBe(UpgradeCommand.MergeLeft);
        error.ShouldBeEmpty();
        Read(".claude/skills/add-slice/SKILL.md").ShouldBe(_generator.Files[".claude/skills/add-slice/SKILL.md"]);
        Read("docs/rules/HS020.md").ShouldBe("# HS020\n");
        Read("src/Demo/Shared/Http/DomainExceptionHandler.cs").ShouldBe("namespace Demo.Shared.Http;\n");
        Read("AGENTS.md").ShouldBe(applicationAgents);
        Read("src/Demo/Features/Rooms/RenameRoom/RenameRoom.cs").ShouldBe("namespace Demo.Features.Rooms.RenameRoom;\n");
        Lines(output).ShouldBe([
            $"==> Upgrading Demo to the template of dotnet hardslice {ToolVersion.Current}, without the sample, since the solution has no src/Demo/Features/Bookings/ nor src/Demo.Domain/Bookings/ (--sample to keep it)",
            $"==> Generating hardslice-api {ToolVersion.Current} as Demo with --no-sample, in a temporary folder",
            "==> HardSlice files rewritten from the template (1). A change made to one of them in the solution is gone: 'git diff' shows it, for a maintainer to put back one that still applies:",
            "    .claude/skills/add-slice/SKILL.md",
            "==> Files added from the template (2):",
            "    docs/rules/HS020.md",
            "    src/Demo/Shared/Http/DomainExceptionHandler.cs",
            "==> Files of the application that differ from the template, with no generation recorded in .hardslice/generation/ to merge from, left as is (1). Merge into each one what the template changed, by hand or with the agent: in the diffs below, '-' lines are in the solution only, '+' lines in the template only:",
            "    AGENTS.md",
            "==> Diff of AGENTS.md",
            "--- AGENTS.md (solution)",
            $"+++ AGENTS.md (template {ToolVersion.Current})",
            "@@ -3,7 +3,8 @@",
            " Golden rules:",
            " ",
            " 1. One slice per use case.",
            "+2. Test every slice.",
            " ",
            " ## Modules",
            " ",
            "-- `Rooms`: the rooms of the building.",
            "+- None yet.",
            "==> The generation of the template is recorded in .hardslice/generation/ (8 files): the next upgrade merges the files of the application from it.",
            "==> Upgrade done: 1 HardSlice file rewritten, 2 files added, 0 updated, 0 merged, 0 removed, 0 conflicts to resolve, 1 file left to merge or to review. Merge the files listed above, review the changes with 'git diff', then run 'dotnet hardslice check'.",
        ]);
        // PB-095: the solution recorded no generation, as Ghostline before its first upgrade: it now records the one of the template.
        Read(".hardslice/generation/AGENTS.md").ShouldBe(_generator.Files["AGENTS.md"]);
        Read(".hardslice/generation/src/Demo/Shared/Http/DomainExceptionHandler.cs").ShouldBe("namespace Demo.Shared.Http;\n");
        Directory.EnumerateFiles(Path.Combine(_solution.Root, ".hardslice", "generation"), "*", SearchOption.AllDirectories).Count().ShouldBe(8);
        File.Exists(Path.Combine(_solution.Root, ".hardslice/generation/.claude/skills/add-slice/SKILL.md")).ShouldBeFalse();
        File.Exists(Path.Combine(_solution.Root, ".hardslice/generation/docs/rules/HS020.md")).ShouldBeFalse();
    }

    // The generation runs once, under the name of the solution, at the version of the tool, in a folder that it then deletes.
    [Fact]
    public void Generates_the_template_at_the_version_of_the_tool_under_the_name_of_the_solution_in_a_temporary_folder()
    {
        Upgrade();

        var call = _generator.Calls.ShouldHaveSingleItem();
        call.Solution.ShouldBe(new Solution(_solution.Root, "Demo"));
        call.Version.ShouldBe(ToolVersion.Current);
        Path.GetFileName(call.Target).ShouldBe("Demo");
        Path.GetDirectoryName(call.Target).ShouldBe(call.WorkDirectory);
        Directory.Exists(call.WorkDirectory).ShouldBeFalse();
    }

    // A protected file changed by hand in the solution, which a maintainer approved, is rewritten and listed as such.
    [Fact]
    public void A_protected_file_changed_in_the_solution_is_rewritten_and_listed()
    {
        _generator.Files[".claude/skills/add-slice/SKILL.md"] = Read(".claude/skills/add-slice/SKILL.md");
        _generator.Files["AGENTS.md"] = Read("AGENTS.md");
        _generator.Files.Remove("docs/rules/HS020.md");
        _generator.Files.Remove("src/Demo/Shared/Http/DomainExceptionHandler.cs");
        _solution.Write("tests/Demo.ArchitectureTests/SliceTests.cs", "// architecture, weakened\n");
        Commit();

        var (exitCode, output, error) = Upgrade();

        exitCode.ShouldBe(0);
        error.ShouldBeEmpty();
        Read("tests/Demo.ArchitectureTests/SliceTests.cs").ShouldBe("// architecture\n");
        Lines(output)[2..].ShouldBe([
            "==> HardSlice files rewritten from the template (1). A change made to one of them in the solution is gone: 'git diff' shows it, for a maintainer to put back one that still applies:",
            "    tests/Demo.ArchitectureTests/SliceTests.cs",
            "==> The generation of the template is recorded in .hardslice/generation/ (7 files): the next upgrade merges the files of the application from it.",
            "==> Upgrade done: 1 HardSlice file rewritten, 0 files added, 0 updated, 0 merged, 0 removed, 0 conflicts to resolve, 0 files left to merge or to review. Review the changes with 'git diff', then run 'dotnet hardslice check'.",
        ]);
    }

    [Fact]
    public void A_tree_with_changes_is_refused_before_the_generation_and_nothing_is_written()
    {
        _solution.Write("src/Demo/Program.cs", "var app = builder.Build();\napp.MapRooms();\napp.Run();\n");
        _solution.Write("src/Demo/Features/Rooms/CloseRoom/CloseRoom.cs", "namespace Demo.Features.Rooms.CloseRoom;\n");

        var (exitCode, output, error) = Upgrade();

        exitCode.ShouldBe(1);
        output.ShouldBeEmpty();
        _generator.Calls.ShouldBeEmpty();
        error.ShouldBe(
            "error: the git tree of the solution has 2 changes not committed: src/Demo/Features/Rooms/CloseRoom/CloseRoom.cs, src/Demo/Program.cs. "
            + "dotnet hardslice upgrade writes many files and starts from a tree without changes, so that 'git diff' shows its own alone. "
            + "Fix: commit or stash them, then run the upgrade again. Only .config/dotnet-tools.json, which the update of the tool changes, may be left. "
            + "Nothing was written." + Environment.NewLine);
        Read(".claude/skills/add-slice/SKILL.md").ShouldBe("---\nname: add-slice\n---\nOld skill.\n");
        File.Exists(Path.Combine(_solution.Root, "docs/rules/HS020.md")).ShouldBeFalse();
    }

    // The update of the tool, which comes first, changes its manifest: the generation writes it again at the same version.
    [Fact]
    public void The_change_of_the_tool_manifest_alone_is_accepted()
    {
        _solution.Write(".config/dotnet-tools.json", "{ \"tools\": {} }");

        var (exitCode, _, error) = Upgrade();

        exitCode.ShouldBe(UpgradeCommand.MergeLeft);
        error.ShouldBeEmpty();
        Read(".config/dotnet-tools.json").ShouldBe("{}");
    }

    [Fact]
    public void A_solution_outside_a_git_repository_is_refused()
    {
        Directory.Delete(Path.Combine(_solution.Root, ".git"), recursive: true);
        // A repository in a parent folder would hold the solution: none is expected around the temporary folders.
        if (Runner.Capture("git", ["rev-parse", "--show-toplevel"], _solution.Root).ExitCode == 0)
            return;

        var (exitCode, _, error) = Upgrade();

        exitCode.ShouldBe(1);
        _generator.Calls.ShouldBeEmpty();
        error.ShouldStartWith($"error: '{_solution.Root}' is not in a git repository, or git cannot run (");
        error.ShouldEndWith("Fix: commit the solution to a git repository, then run the upgrade again. Nothing was written." + Environment.NewLine);
    }

    // A solution in a folder of its repository: the changes around it do not matter, those in it are named from its root.
    [Fact]
    public void A_solution_in_a_folder_of_its_repository_reads_the_changes_of_that_folder_only()
    {
        var repository = Directory.CreateTempSubdirectory("hardslice-repository-").FullName;
        try
        {
            var solution = Path.Combine(repository, "api");
            CopyDirectory(_solution.Root, solution, skip: ".git");
            File.WriteAllText(Path.Combine(repository, "README.md"), "# Product\n");
            GitIn(repository, "init", "--quiet");
            GitIn(repository, "add", "--all");
            GitIn(repository, "-c", "user.name=Test", "-c", "user.email=test@example.com", "-c", "commit.gpgsign=false", "commit", "--quiet", "-m", "solution");
            File.WriteAllText(Path.Combine(repository, "README.md"), "# Product, changed\n");

            var (exitCode, _, error) = Upgrade(solution);
            exitCode.ShouldBe(UpgradeCommand.MergeLeft);
            error.ShouldBeEmpty();
            File.ReadAllText(Path.Combine(solution, "docs/rules/HS020.md")).ShouldBe("# HS020\n");

            File.WriteAllText(Path.Combine(solution, "src/Demo/Program.cs"), "app.Run();\n");
            (exitCode, _, error) = Upgrade(solution);
            exitCode.ShouldBe(1);
            error.ShouldStartWith("error: the git tree of the solution has ");
            error.ShouldContain("src/Demo/Program.cs");
            error.ShouldNotContain("api/");
        }
        finally
        {
            Directory.Delete(repository, recursive: true);
        }
    }

    [Theory]
    [InlineData(null, "src/Demo/Features/Bookings/BookingsModule.cs", true, "with the sample, since the solution has src/Demo/Features/Bookings/ (--no-sample to leave it out)")]
    [InlineData(null, "src/Demo.Domain/Bookings/Booking.cs", true, "with the sample, since the solution has src/Demo.Domain/Bookings/ (--no-sample to leave it out)")]
    [InlineData(null, null, false, "without the sample, since the solution has no src/Demo/Features/Bookings/ nor src/Demo.Domain/Bookings/ (--sample to keep it)")]
    [InlineData(false, "src/Demo/Features/Bookings/BookingsModule.cs", false, "without the sample, as --no-sample asks")]
    [InlineData(true, null, true, "with the sample, as --sample asks")]
    public void The_variant_is_the_one_given_or_the_one_the_sample_module_tells(bool? given, string? sampleFile, bool sample, string description)
    {
        if (sampleFile is not null)
        {
            _solution.Write(sampleFile, "namespace Demo;\n");
            Commit();
        }

        var (_, output, _) = Upgrade(sample: given);

        _generator.Calls.ShouldHaveSingleItem().Sample.ShouldBe(sample);
        Lines(output)[0].ShouldBe($"==> Upgrading Demo to the template of dotnet hardslice {ToolVersion.Current}, {description}");
        Lines(output)[1].ShouldBe($"==> Generating hardslice-api {ToolVersion.Current} as Demo{(sample ? "" : " with --no-sample")}, in a temporary folder");
    }

    // A HardSlice file that the template no longer generates, such as an architecture test it removed, is left and listed.
    [Fact]
    public void A_HardSlice_file_that_the_template_no_longer_generates_is_left_and_listed()
    {
        _generator.Files.Remove("tests/Demo.ArchitectureTests/SliceTests.cs");
        _generator.Files["AGENTS.md"] = Read("AGENTS.md");

        var (exitCode, output, _) = Upgrade();

        exitCode.ShouldBe(UpgradeCommand.MergeLeft);
        Read("tests/Demo.ArchitectureTests/SliceTests.cs").ShouldBe("// architecture\n");
        Lines(output).ShouldContain(
            "==> HardSlice files that the template does not generate, left as is (1). Delete each one that an older template generated, keep one that a maintainer added:");
        Lines(output).ShouldContain("    tests/Demo.ArchitectureTests/SliceTests.cs");
        Lines(output)[^1].ShouldContain(" 1 file left to merge or to review. Merge the files listed above");
    }

    // Ghostline: the template moved the HTTP answers from Shared/Behaviors to Shared/Http. The new file is added, and the old one,
    // which the application may have changed and which would clash with it, is left and listed with the file that replaces it.
    [Fact]
    public void A_file_of_the_solution_with_the_name_of_an_added_file_is_listed_as_maybe_moved()
    {
        _solution.Write("src/Demo/Shared/Behaviors/DomainExceptionHandler.cs", "namespace Demo.Shared.Behaviors;\n");
        Commit();
        _generator.Files["AGENTS.md"] = Read("AGENTS.md");

        var (exitCode, output, _) = Upgrade();

        exitCode.ShouldBe(UpgradeCommand.MergeLeft);
        Read("src/Demo/Shared/Behaviors/DomainExceptionHandler.cs").ShouldBe("namespace Demo.Shared.Behaviors;\n");
        Read("src/Demo/Shared/Http/DomainExceptionHandler.cs").ShouldBe("namespace Demo.Shared.Http;\n");
        var lines = Lines(output);
        lines.ShouldContain(
            "==> Files of the solution that the template may have moved, left as is (1). Each one has the name of a file added from the template: "
            + "merge what the application changed in it into the new file, then delete it:");
        lines.ShouldContain("    src/Demo/Shared/Behaviors/DomainExceptionHandler.cs -> src/Demo/Shared/Http/DomainExceptionHandler.cs");
        lines[^1].ShouldContain(" 1 file left to merge or to review. Merge the files listed above");
    }

    [Fact]
    public void A_failed_generation_fails_the_upgrade_and_writes_nothing()
    {
        _generator.Failure = "error: HardSlice.Templates could not be installed.";

        var (exitCode, _, error) = Upgrade();

        exitCode.ShouldBe(1);
        error.ShouldBe("error: HardSlice.Templates could not be installed." + Environment.NewLine);
        Read(".claude/skills/add-slice/SKILL.md").ShouldBe("---\nname: add-slice\n---\nOld skill.\n");
        Runner.Capture("git", ["status", "--porcelain"], _solution.Root).Output.ShouldBeEmpty();
    }

    // git may check the files out with the line breaks of Windows: a file that differs only by them is the same file.
    [Fact]
    public void A_file_that_differs_only_by_its_line_breaks_is_left_and_not_listed()
    {
        _generator.Files["AGENTS.md"] = Read("AGENTS.md").Replace("\n", "\r\n");
        _generator.Files["scripts/check.sh"] = "dotnet hardslice check\r\n";

        var (_, output, _) = Upgrade();

        output.ShouldNotContain("AGENTS.md");
        output.ShouldNotContain("scripts/check.sh");
        Read("scripts/check.sh").ShouldBe("dotnet hardslice check\n");
    }

    // dotnet new draws a new UserSecretsId at each generation: the project of the solution keeps its own, which is no difference.
    [Fact]
    public void A_project_that_differs_only_by_its_user_secrets_id_is_not_listed()
    {
        const string project = "<Project Sdk=\"Microsoft.NET.Sdk.Web\">\n  <PropertyGroup>\n    <UserSecretsId>{0}</UserSecretsId>\n  </PropertyGroup>\n</Project>\n";
        _solution.Write("src/Demo/Demo.csproj", string.Format(project, "8254d42f-b88e-48d2-83ca-ca1a59059a75"));
        Commit();
        _generator.Files["src/Demo/Demo.csproj"] = string.Format(project, "4568ce66-0fef-4b9c-84ba-da27744c3630");
        _generator.Files["AGENTS.md"] = Read("AGENTS.md");

        var (exitCode, output, _) = Upgrade();

        exitCode.ShouldBe(0);
        output.ShouldNotContain("Demo.csproj");
        Read("src/Demo/Demo.csproj").ShouldContain("8254d42f-b88e-48d2-83ca-ca1a59059a75");
    }

    // The files that the template owns: those an agent never edits, and the rule sheets. Any other file it generates belongs to
    // the application, which changes it: AGENTS.md, Program.cs, AppFactory.cs, the projects and Shared among them.
    [Fact]
    public void The_template_owns_its_protected_files_and_its_rule_sheets_only()
    {
        var files = Directory.EnumerateFiles(Repository.Template, "*", SearchOption.AllDirectories)
            .Select(file => Path.GetRelativePath(Repository.Template, file).Replace('\\', '/'))
            .Where(path => !path.StartsWith(".template.config/", StringComparison.Ordinal) && !path.Contains("/bin/") && !path.Contains("/obj/") && !path.Contains("TestResults/"))
            .ToArray();

        var owned = files.Where(path => UpgradeCommand.OwnedByTemplate(path, "MyApp")).ToArray();

        owned.ShouldContain("hardslice.json");
        owned.ShouldContain("Directory.HardSlice.props");
        owned.ShouldContain(".config/dotnet-tools.json");
        owned.ShouldContain(".claude/skills/add-slice/SKILL.md");
        owned.ShouldContain(".codex/hooks.json");
        owned.ShouldContain(".github/hooks/hardslice.json");
        owned.ShouldContain("scripts/check.sh");
        owned.ShouldContain("tests/MyApp.ArchitectureTests/SliceTests.cs");
        owned.ShouldContain("docs/rules/HS016.md");
        UpgradeCommand.OwnedByTemplate(".hardslice/generation/AGENTS.md", "MyApp").ShouldBeTrue();
        foreach (var path in new[] { "AGENTS.md", "Directory.Packages.props", "src/MyApp/Program.cs", "src/MyApp/MyApp.csproj", "tests/MyApp.IntegrationTests/AppFactory.cs", "src/MyApp/Shared/Messaging/Mediator.cs", "GEMINI.md", ".gitignore" })
            UpgradeCommand.OwnedByTemplate(path, "MyApp").ShouldBeFalse(path);
    }

    // PB-095: Ghostline's first upgrade listed AGENTS.md with its own parts as lines to remove, and 5 of its 10 files that the
    // application never changed. With the generation that the solution records, the upgrade tells the changes of the application
    // from those of the template: it updates a file the application did not change, merges two changes on different lines, and
    // leaves a file that only the application changed.
    [Fact]
    public void The_files_of_the_application_are_merged_in_three_ways_from_the_recorded_generation()
    {
        RecordThreeWayCase();

        var (exitCode, output, error) = Upgrade();

        exitCode.ShouldBe(0);
        error.ShouldBeEmpty();
        Read("AGENTS.md").ShouldBe(
            "# Demo\n\nGolden rules:\n\n1. One slice per use case.\n2. Test every slice.\n\n## Modules\n\n- `Rooms`: the rooms of the building.\n\n## Running\n\nRun it.\n");
        Read("src/Demo/Program.cs").ShouldBe(
            "var builder = WebApplication.CreateBuilder(args);\nbuilder.Services.AddMediator();\nbuilder.Services.AddRooms();\n\nvar app = builder.Build();\napp.MapHealth();\n\nawait app.RunAsync();\n");
        Read("src/Demo/Shared/Messaging/Mediator.cs").ShouldBe("namespace Demo.Shared.Messaging;\n// version 2\n");
        Read("src/Demo/Shared/Persistence/AppDbContext.cs").ShouldBe("namespace Demo.Shared.Persistence;\n// changed by the application\n");
        Lines(output)[2..].ShouldBe([
            "==> HardSlice files rewritten from the template (1). A change made to one of them in the solution is gone: 'git diff' shows it, for a maintainer to put back one that still applies:",
            "    .claude/skills/add-slice/SKILL.md",
            "==> Files added from the template (2):",
            "    docs/rules/HS020.md",
            "    src/Demo/Shared/Http/DomainExceptionHandler.cs",
            "==> Files of the application updated from the template, unchanged by the application (1):",
            "    src/Demo/Shared/Messaging/Mediator.cs",
            "==> Files of the application merged with the template, without conflict (2). Review each one with 'git diff':",
            "    AGENTS.md",
            "    src/Demo/Program.cs",
            "==> .hardslice/generation/ now holds the generation of the template " + ToolVersion.Current + ", the base of the next upgrade.",
            "==> Upgrade done: 1 HardSlice file rewritten, 2 files added, 1 updated, 2 merged, 0 removed, 0 conflicts to resolve, 0 files left to merge or to review. Review the changes with 'git diff', then run 'dotnet hardslice check'.",
        ]);
        foreach (var path in new[] { "AGENTS.md", "src/Demo/Program.cs", "src/Demo/Shared/Messaging/Mediator.cs", "src/Demo/Shared/Persistence/AppDbContext.cs", "src/Demo/Shared/Http/DomainExceptionHandler.cs" })
            Read(".hardslice/generation/" + path).ShouldBe(_generator.Files[path], path);
    }

    // The upgrade after a merge has nothing to write: the solution and the recorded generation already hold the template.
    [Fact]
    public void A_second_upgrade_rewrites_and_lists_nothing()
    {
        RecordThreeWayCase();
        Upgrade().ExitCode.ShouldBe(0);
        Commit();

        var (exitCode, output, error) = Upgrade();

        exitCode.ShouldBe(0);
        error.ShouldBeEmpty();
        Lines(output)[2..].ShouldBe([
            "==> Upgrade done: 0 HardSlice files rewritten, 0 files added, 0 updated, 0 merged, 0 removed, 0 conflicts to resolve, 0 files left to merge or to review. Review the changes with 'git diff', then run 'dotnet hardslice check'.",
        ]);
        Runner.Capture("git", ["status", "--porcelain"], _solution.Root).Output.ShouldBeEmpty();
    }

    // A line that both changed: the file holds both changes between the markers of git, with the recorded generation, and the
    // upgrade exits 3.
    [Fact]
    public void A_line_changed_by_the_application_and_the_template_is_written_as_a_conflict()
    {
        RecordThreeWayCase();
        _solution.Write("AGENTS.md", "# Demo\n\nGolden rules:\n\n1. One slice per use case, always.\n\n## Modules\n\n- `Rooms`: the rooms of the building.\n\n## Running\n\nRun it.\n");
        Commit();
        _generator.Files["AGENTS.md"] = "# Demo\n\nGolden rules:\n\n1. One slice per use case, tested.\n\n## Modules\n\n- None yet.\n\n## Running\n\nRun it.\n";

        var (exitCode, output, error) = Upgrade();

        exitCode.ShouldBe(UpgradeCommand.MergeLeft);
        error.ShouldBeEmpty();
        Read("AGENTS.md").ShouldBe(
            "# Demo\n\nGolden rules:\n\n"
            + "<<<<<<< solution\n1. One slice per use case, always.\n"
            + $"||||||| generation {ToolVersion.Current}\n1. One slice per use case.\n"
            + "=======\n1. One slice per use case, tested.\n"
            + $">>>>>>> template {ToolVersion.Current}\n"
            + "\n## Modules\n\n- `Rooms`: the rooms of the building.\n\n## Running\n\nRun it.\n");
        var lines = Lines(output);
        lines.ShouldContain(
            $"==> Conflicts to resolve (1). Each file holds both changes between git conflict markers: '<<<<<<< solution', then '||||||| generation {ToolVersion.Current}' "
            + $"before the lines as the template generated them, then '=======' before '>>>>>>> template {ToolVersion.Current}'. Keep what each side needs, then remove the markers:");
        lines.ShouldContain("    AGENTS.md");
        lines[^1].ShouldBe(
            "==> Upgrade done: 1 HardSlice file rewritten, 2 files added, 1 updated, 1 merged, 0 removed, 1 conflict to resolve, 0 files left to merge or to review. "
            + "Resolve the conflicts listed above, review the changes with 'git diff', then run 'dotnet hardslice check'.");
        Read(".hardslice/generation/AGENTS.md").ShouldBe(_generator.Files["AGENTS.md"]);
    }

    // dotnet new draws a new UserSecretsId at each generation: the project keeps the one of the solution, without a conflict on
    // its line, and so does its recorded generation.
    [Fact]
    public void The_UserSecretsId_of_a_project_creates_no_conflict()
    {
        const string project = "<Project Sdk=\"Microsoft.NET.Sdk.Web\">\n  <PropertyGroup>\n    <UserSecretsId>{0}</UserSecretsId>\n    <Nullable>enable</Nullable>\n  </PropertyGroup>\n\n  <ItemGroup>\n{1}  </ItemGroup>\n</Project>\n";
        const string kept = "8254d42f-b88e-48d2-83ca-ca1a59059a75";
        Generated("src/Demo/Demo.csproj", string.Format(project, kept, "    <PackageReference Include=\"FluentValidation\" />\n"));
        _solution.Write("src/Demo/Demo.csproj", "<!-- Rooms -->\n" + string.Format(project, kept, "    <PackageReference Include=\"FluentValidation\" />\n    <PackageReference Include=\"CsvHelper\" />\n"));
        Commit();
        _generator.Files["AGENTS.md"] = Read("AGENTS.md");
        _generator.Files["src/Demo/Demo.csproj"] = string.Format(project, "4568ce66-0fef-4b9c-84ba-da27744c3630", "    <PackageReference Include=\"FluentValidation\" />\n").Replace("enable", "disable", StringComparison.Ordinal);

        var (exitCode, output, _) = Upgrade();

        exitCode.ShouldBe(0);
        Lines(output).ShouldContain("    src/Demo/Demo.csproj");
        output.ShouldNotContain("==> Conflicts to resolve");
        Read("src/Demo/Demo.csproj").ShouldBe(
            "<!-- Rooms -->\n" + string.Format(project, kept, "    <PackageReference Include=\"FluentValidation\" />\n    <PackageReference Include=\"CsvHelper\" />\n").Replace("enable", "disable", StringComparison.Ordinal));
        Read(".hardslice/generation/src/Demo/Demo.csproj").ShouldContain(kept);
    }

    // A file that the application deleted is left deleted: listed when the template changed it, silent otherwise.
    [Fact]
    public void A_file_deleted_by_the_application_is_left_deleted_and_listed_when_the_template_changed_it()
    {
        RecordThreeWayCase();
        Generated("src/Demo/Shared/Behaviors/LoggingBehavior.cs", "namespace Demo.Shared.Behaviors;\n");
        File.Delete(Path.Combine(_solution.Root, "src/Demo/Shared/Messaging/Mediator.cs"));
        File.Delete(Path.Combine(_solution.Root, "src/Demo/Shared/Behaviors/LoggingBehavior.cs"));
        Commit();
        _generator.Files["src/Demo/Shared/Behaviors/LoggingBehavior.cs"] = "namespace Demo.Shared.Behaviors;\n";

        var (exitCode, output, _) = Upgrade();

        exitCode.ShouldBe(UpgradeCommand.MergeLeft);
        File.Exists(Path.Combine(_solution.Root, "src/Demo/Shared/Messaging/Mediator.cs")).ShouldBeFalse();
        File.Exists(Path.Combine(_solution.Root, "src/Demo/Shared/Behaviors/LoggingBehavior.cs")).ShouldBeFalse();
        var lines = Lines(output);
        lines.ShouldContain(
            "==> Files that the application deleted and the template changed, left deleted (1). Restore one that the application needs from .hardslice/generation/, which holds the new generation:");
        lines.ShouldContain("    src/Demo/Shared/Messaging/Mediator.cs");
        output.ShouldNotContain("LoggingBehavior.cs");
        lines[^1].ShouldContain(" 1 file left to merge or to review. Merge the files listed above");
        Read(".hardslice/generation/src/Demo/Shared/Messaging/Mediator.cs").ShouldBe(_generator.Files["src/Demo/Shared/Messaging/Mediator.cs"]);
    }

    // A file of the recorded generation that the template no longer generates: deleted when the application never changed it,
    // even when the template moved it, and left and listed when it did. The recorded generation loses it too.
    [Fact]
    public void A_file_that_the_template_no_longer_generates_is_deleted_unless_the_application_changed_it()
    {
        RecordThreeWayCase();
        Generated("src/Demo/Shared/Behaviors/DomainExceptionHandler.cs", "namespace Demo.Shared.Behaviors;\n");
        Generated("src/Demo/Shared/Behaviors/ValidationBehavior.cs", "namespace Demo.Shared.Behaviors;\n");
        _solution.Write("src/Demo/Shared/Behaviors/ValidationBehavior.cs", "namespace Demo.Shared.Behaviors;\n// changed by the application\n");
        Commit();

        var (exitCode, output, _) = Upgrade();

        exitCode.ShouldBe(UpgradeCommand.MergeLeft);
        File.Exists(Path.Combine(_solution.Root, "src/Demo/Shared/Behaviors/DomainExceptionHandler.cs")).ShouldBeFalse();
        Read("src/Demo/Shared/Behaviors/ValidationBehavior.cs").ShouldBe("namespace Demo.Shared.Behaviors;\n// changed by the application\n");
        var lines = Lines(output);
        lines.ShouldContain("==> Files of the application removed, which the template no longer generates and the application did not change (1):");
        lines.ShouldContain("    src/Demo/Shared/Behaviors/DomainExceptionHandler.cs");
        lines.ShouldContain(
            "==> Files of the application that the template no longer generates, changed by the application, left as is (1). Delete each one that the application no longer needs:");
        lines.ShouldContain("    src/Demo/Shared/Behaviors/ValidationBehavior.cs");
        output.ShouldNotContain("may have moved");
        lines[^1].ShouldContain(", 1 removed, 0 conflicts to resolve, 1 file left to merge or to review.");
        Directory.Exists(Path.Combine(_solution.Root, ".hardslice/generation/src/Demo/Shared/Behaviors")).ShouldBeFalse();
    }

    // git may check the files out with the line breaks of Windows: the merged file keeps them.
    [Fact]
    public void A_merged_file_keeps_the_line_breaks_of_the_solution()
    {
        RecordThreeWayCase();
        _solution.Write("src/Demo/Program.cs", Read("src/Demo/Program.cs").Replace("\n", "\r\n", StringComparison.Ordinal));
        _solution.Write("src/Demo/Shared/Messaging/Mediator.cs", Read("src/Demo/Shared/Messaging/Mediator.cs").Replace("\n", "\r\n", StringComparison.Ordinal));
        Commit();

        var (exitCode, output, _) = Upgrade();

        exitCode.ShouldBe(0);
        Read("src/Demo/Program.cs").ShouldBe(
            "var builder = WebApplication.CreateBuilder(args);\r\nbuilder.Services.AddMediator();\r\nbuilder.Services.AddRooms();\r\n\r\nvar app = builder.Build();\r\napp.MapHealth();\r\n\r\nawait app.RunAsync();\r\n");
        Lines(output).ShouldContain("    src/Demo/Shared/Messaging/Mediator.cs");
    }

    // The solution as the template generated it, with its recorded generation, then changed by the application, and the template
    // of the version of the tool, which changed other lines.
    private void RecordThreeWayCase()
    {
        Generated("AGENTS.md", "# Demo\n\nGolden rules:\n\n1. One slice per use case.\n\n## Modules\n\n- None yet.\n\n## Running\n\nRun it.\n");
        _solution.Write("AGENTS.md", "# Demo\n\nGolden rules:\n\n1. One slice per use case.\n\n## Modules\n\n- `Rooms`: the rooms of the building.\n\n## Running\n\nRun it.\n");
        Generated("src/Demo/Program.cs", "var builder = WebApplication.CreateBuilder(args);\nbuilder.Services.AddMediator();\n\nvar app = builder.Build();\napp.MapHealth();\n\napp.Run();\n");
        _solution.Write("src/Demo/Program.cs", "var builder = WebApplication.CreateBuilder(args);\nbuilder.Services.AddMediator();\nbuilder.Services.AddRooms();\n\nvar app = builder.Build();\napp.MapHealth();\n\napp.Run();\n");
        Generated("src/Demo/Shared/Messaging/Mediator.cs", "namespace Demo.Shared.Messaging;\n");
        Generated("src/Demo/Shared/Persistence/AppDbContext.cs", "namespace Demo.Shared.Persistence;\n");
        _solution.Write("src/Demo/Shared/Persistence/AppDbContext.cs", "namespace Demo.Shared.Persistence;\n// changed by the application\n");
        foreach (var path in new[] { "Directory.Packages.props", "Demo.slnx", ".gitignore" }.Concat(_solution.TestProjects.Where(project => !project.Contains("Architecture", StringComparison.Ordinal))))
            Generated(path, Read(path));
        Commit();

        _generator.Files["AGENTS.md"] = "# Demo\n\nGolden rules:\n\n1. One slice per use case.\n2. Test every slice.\n\n## Modules\n\n- None yet.\n\n## Running\n\nRun it.\n";
        _generator.Files["src/Demo/Program.cs"] = "var builder = WebApplication.CreateBuilder(args);\nbuilder.Services.AddMediator();\n\nvar app = builder.Build();\napp.MapHealth();\n\nawait app.RunAsync();\n";
        _generator.Files["src/Demo/Shared/Messaging/Mediator.cs"] = "namespace Demo.Shared.Messaging;\n// version 2\n";
        _generator.Files["src/Demo/Shared/Persistence/AppDbContext.cs"] = "namespace Demo.Shared.Persistence;\n";
    }

    // A file of the application as the template generated it: in the solution and in its recorded generation.
    private void Generated(string path, string text)
    {
        _solution.Write(path, text);
        _solution.Write(UpgradeCommand.GenerationFolder + path, text);
    }

    // dotnet new, in a hive of its own: the package installed from the root of the solution, whose nuget.config chooses its source.
    [Theory]
    [InlineData(true, "")]
    [InlineData(false, " --no-sample")]
    public void The_generation_installs_the_templates_of_the_version_in_a_hive_of_its_own_then_generates_hardslice_api(bool sample, string option)
    {
        var runner = new FakeRunner();
        var work = Path.Combine(Path.GetTempPath(), "work");
        var target = Path.Combine(work, "Demo");

        var generated = new DotnetNewGenerator(runner).Generate(new Solution(_solution.Root, "Demo"), "1.2.3", sample, work, target, new StringWriter());

        generated.ShouldBeTrue();
        var hive = Path.Combine(work, "template-hive");
        runner.Commands.ShouldBe([
            $"dotnet new install HardSlice.Templates@1.2.3 --debug:custom-hive {hive}",
            $"dotnet new hardslice-api --name Demo --output {target}{option} --debug:custom-hive {hive}",
        ]);
        runner.WorkingDirectories.ShouldBe([_solution.Root, work]);
    }

    [Fact]
    public void A_failed_install_names_the_package_and_gives_the_output_of_dotnet_new()
    {
        var runner = new FakeRunner().Failing("dotnet new install", 103, "error: HardSlice.Templates@1.2.3 is not found in NuGet feeds");
        var error = new StringWriter();

        var generated = new DotnetNewGenerator(runner).Generate(new Solution(_solution.Root, "Demo"), "1.2.3", true, "/work", "/work/Demo", error);

        generated.ShouldBeFalse();
        runner.Commands.Count.ShouldBe(1);
        error.ToString().ShouldBe(
            "error: 'dotnet new install HardSlice.Templates@1.2.3 --debug:custom-hive /work/template-hive' exited with code 103: "
            + "HardSlice.Templates 1.2.3 could not be installed. Check that a package source of the nuget.config files of the solution serves it. "
            + "Nothing was written to the solution." + Environment.NewLine
            + "error: HardSlice.Templates@1.2.3 is not found in NuGet feeds" + Environment.NewLine);
    }

    private static readonly ProcessRunner Runner = new(Environment.GetEnvironmentVariable);

    private (int ExitCode, string Output, string Error) Upgrade(string? directory = null, bool? sample = null)
    {
        var output = new StringWriter();
        var error = new StringWriter();
        var exitCode = new UpgradeCommand(Runner, _generator, output, error).Run(directory ?? _solution.Root, sample);
        return (exitCode, output.ToString(), error.ToString());
    }

    private string Read(string path) => File.ReadAllText(Path.Combine(_solution.Root, path));

    private static string[] Lines(string text) => text.Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries);

    private void Commit()
    {
        Git("add", "--all");
        Git("-c", "user.name=Test", "-c", "user.email=test@example.com", "-c", "commit.gpgsign=false", "commit", "--quiet", "--allow-empty", "-m", "solution");
    }

    private void Git(params string[] arguments) => GitIn(_solution.Root, arguments);

    private static void GitIn(string directory, params string[] arguments)
    {
        var result = Runner.Capture("git", arguments, directory);
        result.ExitCode.ShouldBe(0, $"git {string.Join(' ', arguments)}: {result.Error}");
    }

    private static void CopyDirectory(string source, string target, string skip)
    {
        foreach (var file in Directory.EnumerateFiles(source, "*", SearchOption.AllDirectories))
        {
            var relative = Path.GetRelativePath(source, file);
            if (relative.StartsWith(skip + Path.DirectorySeparatorChar, StringComparison.Ordinal))
                continue;
            Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(target, relative))!);
            File.Copy(file, Path.Combine(target, relative));
        }
    }

    // Writes its files into the target folder, as dotnet new would generate the template, or fails with its message.
    private sealed class FakeGenerator : ITemplateGenerator
    {
        public Dictionary<string, string> Files { get; } = [];

        public List<(Solution Solution, string Version, bool Sample, string WorkDirectory, string Target)> Calls { get; } = [];

        public string? Failure { get; set; }

        public bool Generate(Solution solution, string version, bool sample, string workDirectory, string target, TextWriter error)
        {
            Calls.Add((solution, version, sample, workDirectory, target));
            if (Failure is not null)
            {
                error.WriteLine(Failure);
                return false;
            }

            foreach (var (path, text) in Files)
            {
                Write(target, path, text);
                // The second source of template.json: the files of the application again, in the generation that the solution records.
                if (!UpgradeCommand.OwnedByTemplate(path, solution.Name) && !UpgradeCommand.AgentInstructionFiles.Contains(path))
                    Write(target, UpgradeCommand.GenerationFolder + path, text);
            }

            return true;
        }

        private static void Write(string target, string path, string text)
        {
            var file = Path.Combine(target, path);
            Directory.CreateDirectory(Path.GetDirectoryName(file)!);
            File.WriteAllText(file, text);
        }
    }
}
